// @ts-check

import { Command } from '../../utils/Command.js'
import { CommandType } from '../../utils/CommandType.js'
import { RuntimeName } from '../../utils/RuntimeName.js'
import { Color, Point, colorChannel } from '../../utils/DrawingTypes.js'

/**
 * @typedef {import('../../types.d.ts').RuntimeName} RuntimeName
 */

/** @type {Record<number, string>} */
const pointTypeByRuntime = {
    [RuntimeName.Nodejs]: 'Point',
    [RuntimeName.Jvm]: 'java.awt.Point',
    [RuntimeName.Netcore]: 'System.Drawing.Point',
    [RuntimeName.Clr]: 'System.Drawing.Point',
}

/** @type {Record<number, string>} */
const colorTypeByRuntime = {
    [RuntimeName.Nodejs]: 'Color',
    [RuntimeName.Jvm]: 'java.awt.Color',
    [RuntimeName.Netcore]: 'System.Drawing.Color',
    [RuntimeName.Clr]: 'System.Drawing.Color',
}

/** @type {Function[]} */
const parsableTypeConstructors = [Date, URL, Point, Color]

export class ValueTypeParser {
    /**
     * @param {any} value
     * @returns {boolean}
     */
    static isParsableValueType(value) {
        return parsableTypeConstructors.some((constructorType) => value instanceof constructorType)
    }

    /**
     * @param {any} type
     * @returns {boolean}
     */
    static isParsableValueTypeByType(type) {
        return (
            typeof type === 'function' &&
            (parsableTypeConstructors.includes(type) ||
                parsableTypeConstructors.some((constructorType) => constructorType.name === type.name))
        )
    }

    /**
     * @param {any} value
     * @param {RuntimeName} runtimeName
     * @returns {Command}
     */
    static getCommandForParsableValueType(value, runtimeName) {
        if (value instanceof Date) {
            return new Command(runtimeName, CommandType.ComplexValueType, ['Date', value.toISOString()])
        }
        if (value instanceof URL) {
            return new Command(runtimeName, CommandType.ComplexValueType, ['URL', value.href])
        }
        if (value instanceof Point) {
            return new Command(runtimeName, CommandType.ComplexValueType, ['Point', value.x, value.y])
        }
        if (value instanceof Color) {
            return new Command(runtimeName, CommandType.ComplexValueType, [
                'Color',
                colorChannel(value.a),
                colorChannel(value.r),
                colorChannel(value.g),
                colorChannel(value.b),
            ])
        }
        throw new Error(`Unsupported value type: ${Object.prototype.toString.call(value)}`)
    }
}
